window.OCRoomPresets = {
    entries: [ {
        id: "gate-water",
        name: "水闸业力门",
        type: "GATE",
        w: 72,
        h: 65,
        gzip: ""
    }, {
        id: "gate-dry",
        name: "干式业力门",
        type: "GATE",
        w: 72,
        h: 65,
        gzip: ""
    }, {
        id: "gate-su-hi",
        name: "郊区式业力门",
        type: "GATE",
        w: 72,
        h: 65,
        gzip: ""
    }, {
        id: "shelter",
        name: "标准庇护所",
        type: "SHELTER",
        w: 72,
        h: 43,
        gzip: ""
    } ],
    async read(id) {
        const entry = this.entries.find(p => p.id === id);
        if (!entry) throw Error("预设不存在。");
        const bytes = Uint8Array.from(atob(entry.gzip), c => c.charCodeAt(0));
        const text = await new Response(new Blob([ bytes ]).stream().pipeThrough(new DecompressionStream("gzip"))).text();
        return OCMapCore.parseRainedRoom(text);
    }
};
